# ============================================================
# CONFIG / SECRETS
# ============================================================

def get_secret(name, default=None):
    try:
        return st.secrets[name]
    except Exception:
        return default


SUPABASE_URL = get_secret("SUPABASE_URL")
SUPABASE_KEY = get_secret("SUPABASE_KEY")
CLIENT_CREDENTIALS = dict(get_secret("CLIENT_CREDENTIALS", {}) or {})

CLEAN_STATUSES = ["Auto-Confirmed", "Confirmed"]
ALL_KNOWN_STATUSES = [
    "Auto-Confirmed",
    "Confirmed",
    "Risk Flagged",
    "Rejected",
    "Cancelled",
    "Manual Review",
    "Pending",
]

STATUS_COLOR_MAP = {
    "Auto-Confirmed": "#16A34A",
    "Confirmed": "#22C55E",
    "Risk Flagged": "#D97706",
    "Rejected": "#DC2626",
    "Cancelled": "#64748B",
    "Manual Review": "#7C3AED",
    "Pending": "#2563EB",
}


# ============================================================
# AUTHENTICATION
# ============================================================
if "auth" not in st.session_state:
    st.session_state.auth = False
if "client_id" not in st.session_state:
    st.session_state.client_id = None
if "show_password" not in st.session_state:
    st.session_state.show_password = False


if not st.session_state.auth:
    st.markdown('<div class="login-shell"><div class="login-card">', unsafe_allow_html=True)
    st.markdown(f'<div class="login-logo-wrap">{brand_icon(76)}</div>', unsafe_allow_html=True)
    st.markdown('<div class="login-title">Welcome to Wapsi</div>', unsafe_allow_html=True)
    st.markdown('<div class="login-kicker">Sign in to your operations workspace</div>', unsafe_allow_html=True)
    st.markdown(
        '<div class="login-brand">Parcel ki <span>Wapsi</span> Khatam · Profit ki <strong>Wapsi</strong> Shuru<br>'
        '<b>AI Operational Intelligence</b> for Ecommerce</div>',
        unsafe_allow_html=True,
    )

    pw_col, toggle_col = st.columns([8, 1])
    with pw_col:
        pw = st.text_input(
            "Password",
            type="default" if st.session_state.show_password else "password",
            placeholder="Enter your workspace password",
            label_visibility="collapsed",
            key="login_password",
        )
    with toggle_col:
        st.write("")
        if st.button("Show" if not st.session_state.show_password else "Hide", use_container_width=True):
            st.session_state.show_password = not st.session_state.show_password
            st.rerun()

    if st.button("Sign in to Wapsi", use_container_width=True, type="primary"):
        if not SUPABASE_URL or not SUPABASE_KEY:
            st.error("Wapsi is not configured correctly. Add SUPABASE_URL and SUPABASE_KEY to Streamlit secrets.")
        elif not CLIENT_CREDENTIALS:
            st.error("No client credentials are configured. Add CLIENT_CREDENTIALS to Streamlit secrets.")
        elif pw in CLIENT_CREDENTIALS:
            st.session_state.auth = True
            st.session_state.client_id = str(CLIENT_CREDENTIALS[pw])
            st.session_state.show_password = False
            st.rerun()
        else:
            st.error("Incorrect password. Please check your credentials and try again.")

    st.markdown('<div class="login-footer">Secure operations workspace · Pakistan</div>', unsafe_allow_html=True)
    st.markdown('</div></div>', unsafe_allow_html=True)
    st.stop()

CURRENT_CLIENT_ID = str(st.session_state.client_id)

# ============================================================
# DATA ACCESS / NORMALIZATION
# ============================================================
@st.cache_data(ttl=60, show_spinner=False)
def load_data(client_id: str):
    if not SUPABASE_URL or not SUPABASE_KEY:
        return pd.DataFrame(), "Missing Supabase configuration."
    try:
        client = create_client(SUPABASE_URL, SUPABASE_KEY)
        response = (
            client.table("orders")
            .select("*")
            .eq("store_id", client_id)
            .order("inserted_at", desc=True)
            .execute()
        )
        df = pd.DataFrame(response.data or [])
        if df.empty:
            return pd.DataFrame(), None

        df.columns = [str(c).strip().lower() for c in df.columns]

        # Ensure expected columns exist so a partially populated row cannot crash the UI.
        defaults = {
            "status": "Pending",
            "city": "Unknown",
            "risk_level": "UNKNOWN",
            "risk_score": 0,
            "price": 0,
            "name": "Unknown customer",
            "phone": "",
            "address": "",
            "clean_address": "",
            "risk_reason": "",
            "map_status": "",
            "created_at": "",
            "inserted_at": None,
        }
        for col, default in defaults.items():
            if col not in df.columns:
                df[col] = default

        df["status"] = df["status"].fillna("Pending").astype(str).str.strip()
        df.loc[df["status"].isin(["", "nan", "None"]), "status"] = "Pending"

        df["city"] = df["city"].fillna("Unknown").astype(str).str.strip().str.title()
        df.loc[df["city"].isin(["", "Nan", "None"]), "city"] = "Unknown"

        df["risk_level"] = df["risk_level"].fillna("UNKNOWN").astype(str).str.strip().str.upper()
        df["risk_score"] = pd.to_numeric(df["risk_score"], errors="coerce").fillna(0).clip(0, 100)
        df["price"] = pd.to_numeric(df["price"], errors="coerce").fillna(0)

        for col in ["name", "phone", "address", "clean_address", "risk_reason", "map_status"]:
            df[col] = df[col].fillna("").astype(str).str.strip()

        if "inserted_at" in df.columns:
            df["inserted_at"] = pd.to_datetime(df["inserted_at"], errors="coerce", utc=True)
            df["inserted_at_pk"] = df["inserted_at"].dt.tz_convert(PAKISTAN_TZ)
            df["date"] = df["inserted_at_pk"].dt.date
        else:
            df["date"] = pd.NaT

        return df, None
    except Exception as exc:
        return pd.DataFrame(), f"Supabase error: {exc}"


# ============================================================
# SIDEBAR FILTERS
# ============================================================
with st.sidebar:
    st.markdown(
        f'''<div class="sidebar-brand"><div class="sidebar-brand-row">{brand_icon(42)}<div><div class="sidebar-name">Wapsi</div><div class="sidebar-client">{CURRENT_CLIENT_ID}</div></div></div></div>''',
        unsafe_allow_html=True,
    )

    st.markdown('<div class="filter-label">Date range</div>', unsafe_allow_html=True)
    date_range = st.selectbox("Date range", ["All time", "Today", "Last 7 days", "Last 30 days"], label_visibility="collapsed")

    st.markdown('<div class="filter-label">Order status</div>', unsafe_allow_html=True)
    status_filter = st.selectbox("Order status", ["All"] + ALL_KNOWN_STATUSES, label_visibility="collapsed")

    st.markdown('<div class="filter-label">Risk level</div>', unsafe_allow_html=True)
    risk_filter = st.selectbox("Risk level", ["All", "CRITICAL", "HIGH", "MEDIUM", "LOW", "UNKNOWN"], label_visibility="collapsed")

    st.markdown('<div class="filter-label">Financial assumptions</div>', unsafe_allow_html=True)
    avg_order_val = st.number_input("Average order value (Rs)", value=3000, step=500, min_value=0)
    shipping_cost = st.number_input("Shipping cost (Rs)", value=250, step=50, min_value=0)
    reverse_cost = st.number_input("Reverse cost (Rs)", value=150, step=50, min_value=0)

    st.markdown('<div class="sidebar-note">Financial impact is modeled from your configured average order value and logistics assumptions.</div>', unsafe_allow_html=True)
    st.divider()

    b1, b2 = st.columns(2)
    with b1:
        if st.button("Refresh", use_container_width=True):
            st.cache_data.clear()
            st.rerun()
    with b2:
        if st.button("Logout", use_container_width=True):
            st.session_state.auth = False
            st.session_state.client_id = None
            st.rerun()

# ============================================================
# LOAD + FILTER DATA
# ============================================================
df_raw, load_error = load_data(CURRENT_CLIENT_ID)

if load_error:
    st.error(load_error)
    st.stop()

if df_raw.empty:
    now_str = datetime.now(PAKISTAN_TZ).strftime("%d %b %Y · %I:%M %p PKT")
    st.markdown(
        f'''<div class="topbar"><div class="topbar-left">{brand_icon(46)}<div><div class="topbar-title">Wapsi</div><div class="topbar-sub">AI Operational Intelligence System for Ecommerce · Pakistan</div></div></div><div class="topbar-right"><div class="live-pill"><span class="live-dot"></span> LIVE</div><div class="topbar-meta">{now_str}</div></div></div>''',
        unsafe_allow_html=True,
    )
    st.markdown('<div class="empty-state"><div class="empty-state-title">No orders found for this workspace</div><div>Wapsi is connected, but there are no order records matching this client ID yet.</div></div>', unsafe_allow_html=True)
    st.stop()

# Dynamic city filter is intentionally placed after data load.
all_cities = sorted(df_raw["city"].dropna().unique().tolist())
with st.sidebar:
    st.markdown('<div class="filter-label">City</div>', unsafe_allow_html=True)
    city_filter = st.selectbox("City", ["All"] + all_cities, label_visibility="collapsed")

# Date filtering uses Pakistan time, not server-local time.
df = df_raw.copy()
today = datetime.now(PAKISTAN_TZ).date()
if "date" in df.columns:
    if date_range == "Today":
        df = df[df["date"] == today]
    elif date_range == "Last 7 days":
        df = df[df["date"] >= today - timedelta(days=7)]
    elif date_range == "Last 30 days":
        df = df[df["date"] >= today - timedelta(days=30)]

# Pending orders remain a separate bucket so the Pending filter actually works.
df_pending = df[df["status"].isin(["Pending", "", "Not Checked"])].copy()
df_proc = df[~df["status"].isin(["Pending", "", "Not Checked"])].copy()

df_view = df_proc.copy()
if status_filter == "Pending":
    df_view = df_pending.copy()
elif status_filter != "All":
    df_view = df_view[df_view["status"] == status_filter]
if city_filter != "All":
    df_view = df_view[df_view["city"] == city_filter]
if risk_filter != "All":
    df_view = df_view[df_view["risk_level"] == risk_filter]

# ============================================================
# BUSINESS METRICS
# ============================================================
total = len(df_proc)
confirmed = int(df_proc["status"].isin(CLEAN_STATUSES).sum())
flagged = int((df_proc["status"] == "Risk Flagged").sum())
rejected = int((df_proc["status"] == "Rejected").sum())
cancelled = int((df_proc["status"] == "Cancelled").sum())
manual_rev = int((df_proc["status"] == "Manual Review").sum())
pending = len(df_pending)

rto_unit = shipping_cost + reverse_cost
clean_pct = round(confirmed / total * 100, 1) if total else 0
risk_pct = round((flagged + rejected) / total * 100, 1) if total else 0
avg_risk = round(float(df_proc["risk_score"].mean()), 1) if total else 0

saved = rejected * avg_order_val
money_at_risk = flagged * avg_order_val
rto_loss = rejected * rto_unit
conf_revenue = confirmed * avg_order_val
worst_case = (flagged + rejected) * rto_unit

fl_df = df_proc[df_proc["status"].isin(["Risk Flagged", "Rejected"])]
avg_fl_risk = round(float(fl_df["risk_score"].mean()), 1) if len(fl_df) else 0
critical_cnt = int((df_proc["risk_score"] >= 85).sum())
border_cnt = int(((df_proc["risk_score"] >= 60) & (df_proc["risk_score"] < 85)).sum())

# ============================================================
# TOP BAR
# ============================================================
now_str = datetime.now(PAKISTAN_TZ).strftime("%d %b %Y · %I:%M %p PKT")
st.markdown(
    f'''<div class="topbar"><div class="topbar-left">{brand_icon(46)}<div><div class="topbar-title">Wapsi</div><div class="topbar-sub">AI Operational Intelligence System for Ecommerce · Pakistan</div></div></div><div class="topbar-right"><div class="live-pill"><span class="live-dot"></span> LIVE · auto-refresh 60s</div><div class="topbar-meta">{now_str} · {total} processed · {pending} pending</div></div></div>''',
    unsafe_allow_html=True,
)

st.markdown(
    f'<div class="page-intro"><div class="page-title">Operations overview</div><div class="page-subtitle">Monitor order quality, financial exposure, and AI validation performance for <b>{CURRENT_CLIENT_ID}</b>.</div></div>',
    unsafe_allow_html=True,
)

# ============================================================
# FILTER SUMMARY
# ============================================================
