# ============================================================
# KPI HELPERS
# ============================================================
def section(title):
    st.markdown(f'<div class="section-heading"><h3>{title}</h3><div class="section-heading-line"></div></div>', unsafe_allow_html=True)


def kpi_card(label, value, sub, accent, icon):
    return f'''<div class="kpi-card" style="--accent:{accent};"><div class="kpi-icon">{icon}</div><div class="kpi-label">{label}</div><div class="kpi-value">{value}</div><div class="kpi-sub">{sub}</div></div>'''


# ============================================================
# ORDER OVERVIEW
# ============================================================
section("Order overview")
kcols = st.columns(7)
order_kpis = [
    ("Total processed", f"{total:,}", "Validated orders", "#64748B", "01"),
    ("Confirmed", f"{confirmed:,}", f"{clean_pct}% clean rate", "#16A34A", "02"),
    ("Risk flagged", f"{flagged:,}", "Awaiting customer reply", "#D97706", "03"),
    ("Rejected", f"{rejected:,}", "Blocked before dispatch", "#DC2626", "04"),
    ("Cancelled", f"{cancelled:,}", "Customer requested cancel", "#64748B", "05"),
    ("Pending / stuck", f"{pending:,}", "Not yet processed", "#2563EB", "06"),
    ("Avg risk score", f"{avg_risk:.1f}", "0 clean · 100 high risk", "#7C3AED", "07"),
]
for col, item in zip(kcols, order_kpis):
    with col:
        st.markdown(kpi_card(*item), unsafe_allow_html=True)

