# ============================================================
# ANALYTICS
# ============================================================
section("Analytics")
c1, c2, c3 = st.columns([1.0, 1.45, 0.95])
PAPER = "rgba(0,0,0,0)"
FONT = "DM Sans"

with c1:
    st.markdown('<div class="panel"><div class="panel-title">Order status split</div><div class="panel-subtitle">Processed orders by outcome</div>', unsafe_allow_html=True)
    sc = df_proc["status"].value_counts().reset_index()
    sc.columns = ["status", "count"]
    if not sc.empty:
        fig1 = px.pie(sc, values="count", names="status", hole=0.68, color="status", color_discrete_map=STATUS_COLOR_MAP)
        fig1.update_traces(textposition="inside", textinfo="percent", marker=dict(line=dict(color="#FFFFFF", width=2)))
        fig1.add_annotation(text=f"<b>{clean_pct}%</b><br>confirmed", x=0.5, y=0.5, showarrow=False, font=dict(size=16, color="#344054", family=FONT))
        fig1.update_layout(
            paper_bgcolor=PAPER,
            plot_bgcolor=PAPER,
            showlegend=True,
            legend=dict(orientation="h", y=-0.05, x=0.5, xanchor="center", font=dict(size=9)),
            margin=dict(t=8, b=25, l=5, r=5),
            height=300,
            font_family=FONT,
        )
        st.plotly_chart(fig1, use_container_width=True, config={"displayModeBar": False})
    else:
        st.info("No processed orders in the selected scope.")
    st.markdown('</div>', unsafe_allow_html=True)

with c2:
    st.markdown('<div class="panel"><div class="panel-title">Order quality by city</div><div class="panel-subtitle">Top cities by order volume · risk shown separately</div>', unsafe_allow_html=True)
    if total > 0:
        cs = df_proc.groupby("city").agg(
            total=("status", "size"),
            risky=("status", lambda x: x.isin(["Risk Flagged", "Rejected"]).sum()),
        ).reset_index()
        cs["confirmed_or_other"] = cs["total"] - cs["risky"]
        cs["risk_pct"] = (cs["risky"] / cs["total"] * 100).round(1)
        cs = cs.sort_values(["total", "risk_pct"], ascending=[False, False]).head(10).sort_values("risk_pct")

        fig2 = go.Figure()
        fig2.add_trace(go.Bar(y=cs["city"], x=cs["confirmed_or_other"], name="Other / confirmed", orientation="h", marker_color="#16A34A", hovertemplate="%{y}<br>Other / confirmed: %{x}<extra></extra>"))
        fig2.add_trace(go.Bar(y=cs["city"], x=cs["risky"], name="Flagged / rejected", orientation="h", marker_color="#DC2626", hovertemplate="%{y}<br>Flagged / rejected: %{x}<extra></extra>"))
        fig2.update_layout(
            barmode="stack", paper_bgcolor=PAPER, plot_bgcolor=PAPER, font_family=FONT,
            xaxis=dict(showgrid=False, showticklabels=False),
            yaxis=dict(showgrid=False, tickfont=dict(size=10, color="#344054")),
            legend=dict(orientation="h", y=1.10, x=0.5, xanchor="center", font=dict(size=9)),
            margin=dict(t=25, b=5, l=5, r=5), height=300, bargap=0.28,
        )
        st.plotly_chart(fig2, use_container_width=True, config={"displayModeBar": False})
    else:
        st.info("No processed orders in the selected scope.")
    st.markdown('</div>', unsafe_allow_html=True)

with c3:
    st.markdown('<div class="panel"><div class="panel-title">Average risk score</div><div class="panel-subtitle">Lower is healthier</div>', unsafe_allow_html=True)
    gauge_color = "#16A34A" if avg_risk < 30 else ("#D97706" if avg_risk < 60 else "#DC2626")
    fig3 = go.Figure(go.Indicator(
        mode="gauge+number",
        value=avg_risk,
        number={"font": {"size": 42, "color": gauge_color, "family": FONT}},
        gauge={
            "axis": {"range": [0, 100], "tickfont": {"size": 9, "color": "#98A2B3"}},
            "bar": {"color": gauge_color, "thickness": 0.25},
            "bgcolor": "#F8FAFC",
            "bordercolor": "#E5E7EB",
            "borderwidth": 1,
            "steps": [
                {"range": [0, 30], "color": "#F0FDF4"},
                {"range": [30, 70], "color": "#FFFBEB"},
                {"range": [70, 100], "color": "#FEF2F2"},
            ],
            "threshold": {"line": {"color": "#DC2626", "width": 2}, "value": 70},
        },
    ))
    fig3.update_layout(paper_bgcolor=PAPER, font_family=FONT, margin=dict(t=15, b=5, l=18, r=18), height=300)
    st.plotly_chart(fig3, use_container_width=True, config={"displayModeBar": False})
    st.markdown(f'<div style="text-align:center;color:#667085;font-size:11px;">{critical_cnt} critical · {border_cnt} borderline</div>', unsafe_allow_html=True)
    st.markdown('</div>', unsafe_allow_html=True)

# ============================================================
# BUSINESS INSIGHTS
# ============================================================
section("Business insights")
ins1, ins2 = st.columns(2)

with ins1:
    if clean_pct >= 70:
        st.markdown(f'<div class="insight" style="--accent:#16A34A"><div class="insight-title">Order quality is healthy</div><div class="insight-body"><strong>{clean_pct}%</strong> of processed orders are confirmed clean. Continue monitoring city-level risk concentrations.</div></div>', unsafe_allow_html=True)
    elif clean_pct >= 50:
        st.markdown(f'<div class="insight" style="--accent:#D97706"><div class="insight-title">Order quality needs attention</div><div class="insight-body">Only <strong>{clean_pct}%</strong> of processed orders are confirmed clean. Review high-risk cities and checkout address quality.</div></div>', unsafe_allow_html=True)
    else:
        st.markdown(f'<div class="insight" style="--accent:#DC2626"><div class="insight-title">Order quality is critical</div><div class="insight-body">Only <strong>{clean_pct}%</strong> of processed orders are confirmed clean. Review validation rules and checkout data immediately.</div></div>', unsafe_allow_html=True)

    per1k = round(saved * 1000 / max(1, total))
    st.markdown(f'<div class="insight" style="--accent:#2563EB"><div class="insight-title">AI system value generated</div><div class="insight-body">Blocked <strong>{rejected} rejected orders</strong> before dispatch, representing <strong>Rs {saved:,}</strong> in modeled avoided order value. Current rate: <strong>Rs {per1k:,} per 1,000 processed orders</strong>.</div></div>', unsafe_allow_html=True)

    daily_est = max(1, round(total / 7))
    net = (saved * 4) - (rto_loss * 4)
    net_color = "#16A34A" if net >= 0 else "#DC2626"
    st.markdown(f'<div class="insight" style="--accent:#7C3AED"><div class="insight-title">Monthly financial projection</div><div class="insight-body">Estimated volume: <strong>~{daily_est} orders/day</strong><br>Projected RTO loss: <strong>Rs {rto_loss * 4:,}</strong><br>Projected modeled savings: <strong>Rs {saved * 4:,}</strong><br>Projected net position: <strong style="color:{net_color}">Rs {net:,}</strong></div></div>', unsafe_allow_html=True)

    if pending > 0:
        st.markdown(f'<div class="insight" style="--accent:#2563EB"><div class="insight-title">{pending} orders are still pending</div><div class="insight-body">These orders have not reached a processed status. Review your n8n workflow, wait nodes, or AI validation step if the queue is not expected.</div></div>', unsafe_allow_html=True)

with ins2:
    if total > 0:
        risk_by_city = df_proc[df_proc["status"].isin(["Risk Flagged", "Rejected"])]
        city_counts = df_proc["city"].value_counts()
        if not risk_by_city.empty:
            top_city = risk_by_city["city"].value_counts().index[0]
            top_risk_count = int(risk_by_city["city"].value_counts().iloc[0])
            top_total = int(city_counts.get(top_city, 1))
            top_pct = round(top_risk_count / max(top_total, 1) * 100, 1)
            st.markdown(f'<div class="insight" style="--accent:#DC2626"><div class="insight-title">Highest risk concentration: {top_city}</div><div class="insight-body"><strong>{top_risk_count} flagged or rejected</strong> out of {top_total} orders from {top_city} — a <strong>{top_pct}% risk rate</strong>.</div></div>', unsafe_allow_html=True)

        rates = {}
        for city in city_counts.index:
            cdf = df_proc[df_proc["city"] == city]
            if len(cdf) >= 2:
                rates[city] = float(cdf["status"].isin(["Risk Flagged", "Rejected"]).mean())
        if rates:
            best_city = min(rates, key=rates.get)
            best_pct = round(rates[best_city] * 100, 1)
            st.markdown(f'<div class="insight" style="--accent:#16A34A"><div class="insight-title">Most reliable city: {best_city}</div><div class="insight-body">Only <strong>{best_pct}% risk rate</strong> across {int(city_counts[best_city])} orders. This may be a candidate for faster processing rules after sufficient sample size.</div></div>', unsafe_allow_html=True)

    st.markdown(f'<div class="insight" style="--accent:#D97706"><div class="insight-title">Risk score breakdown</div><div class="insight-body"><strong>{critical_cnt} orders</strong> scored 85+ · <strong>{border_cnt} orders</strong> scored 60–84 · Overall average: <strong>{avg_risk}</strong> · Flagged/rejected average: <strong>{avg_fl_risk}</strong></div></div>', unsafe_allow_html=True)

    exposure = money_at_risk + rto_loss
    st.markdown(f'<div class="insight" style="--accent:#DC2626"><div class="insight-title">Current modeled exposure</div><div class="insight-body"><strong>Rs {exposure:,}</strong> total current exposure<br>Rs {money_at_risk:,} flagged order value still recoverable<br>Rs {rto_loss:,} modeled logistics loss from rejected orders</div></div>', unsafe_allow_html=True)

