section("Order intelligence")
st.caption(f"Showing {len(df_view):,} orders in the current filter scope · {pending:,} pending overall")

if df_view.empty:
    st.markdown('<div class="empty-state"><div class="empty-state-title">No orders match the current filters</div><div>Try changing the date, status, risk level, or city filter.</div></div>', unsafe_allow_html=True)
else:
    preferred_cols = [
        "name", "phone", "city", "status", "risk_score", "risk_level",
        "risk_reason", "price", "address", "clean_address", "map_status", "created_at",
    ]
    show_cols = [c for c in preferred_cols if c in df_view.columns]
    display_df = df_view[show_cols].copy()

    rename_map = {
        "name": "Customer",
        "phone": "Phone",
        "city": "City",
        "status": "Status",
        "risk_score": "Risk score",
        "risk_level": "Risk level",
        "risk_reason": "AI risk reason",
        "price": "Order value",
        "address": "Raw address",
        "clean_address": "Clean address",
        "map_status": "Maps status",
        "created_at": "Created",
    }
    display_df = display_df.rename(columns=rename_map)

    column_config = {
        "Customer": st.column_config.TextColumn("Customer", width="medium"),
        "Phone": st.column_config.TextColumn("Phone", width="small"),
        "City": st.column_config.TextColumn("City", width="small"),
        "Status": st.column_config.TextColumn("Status", width="medium"),
        "Risk score": st.column_config.ProgressColumn("Risk score", min_value=0, max_value=100, format="%d"),
        "Risk level": st.column_config.TextColumn("Risk level", width="small"),
        "AI risk reason": st.column_config.TextColumn("AI risk reason", width="large"),
        "Order value": st.column_config.NumberColumn("Order value", format="Rs %d"),
        "Raw address": st.column_config.TextColumn("Raw address", width="large"),
        "Clean address": st.column_config.TextColumn("Clean address", width="large"),
        "Maps status": st.column_config.TextColumn("Maps status", width="medium"),
        "Created": st.column_config.TextColumn("Created", width="medium"),
    }

    st.dataframe(display_df, use_container_width=True, height=470, hide_index=True, column_config=column_config)

    # Optional full-detail view without forcing every column into the primary table.
    with st.expander("View full order record"):
        if "name" in df_view.columns:
            customer_options = df_view["name"].replace("", "Unknown customer").tolist()
            selected_customer = st.selectbox("Select an order", customer_options, key="selected_order_customer")
            selected = df_view[df_view["name"] == selected_customer].head(1)
            if not selected.empty:
                record = selected.iloc[0].to_dict()
                detail_cols = st.columns(2)
                items = list(record.items())
                for i, (key, value) in enumerate(items):
                    with detail_cols[i % 2]:
                        st.markdown(f"**{key.replace('_', ' ').title()}**")
                        st.write(value if pd.notna(value) else "")

